proposal.view:
{
  "version": 1,
  "state": [
    {
      "id": "unmounted",
      "when": {
        "eq": [
          {
            "var": "mounted"
          },
          "FALSE"
        ]
      },
      "label": "Hook unmounted"
    },
    {
      "id": "compiling_with_result",
      "when": {
        "all": [
          {
            "eq": [
              {
                "var": "status"
              },
              "\"compiling\""
            ]
          },
          {
            "not": {
              "eq": [
                {
                  "var": "result"
                },
                "0"
              ]
            }
          }
        ]
      },
      "label": "Compiling; previous result retained"
    },
    {
      "id": "compiling",
      "when": {
        "eq": [
          {
            "var": "status"
          },
          "\"compiling\""
        ]
      },
      "label": "Compiling"
    },
    {
      "id": "done",
      "when": {
        "eq": [
          {
            "var": "status"
          },
          "\"done\""
        ]
      },
      "label": "Latest compile succeeded"
    },
    {
      "id": "error",
      "when": {
        "eq": [
          {
            "var": "status"
          },
          "\"error\""
        ]
      },
      "label": "Latest compile failed"
    },
    {
      "id": "timeout",
      "when": {
        "eq": [
          {
            "var": "status"
          },
          "\"timeout\""
        ]
      },
      "label": "Latest compile timed out"
    },
    {
      "id": "idle_with_result",
      "when": {
        "all": [
          {
            "eq": [
              {
                "var": "status"
              },
              "\"idle\""
            ]
          },
          {
            "not": {
              "eq": [
                {
                  "var": "result"
                },
                "0"
              ]
            }
          }
        ]
      },
      "label": "Idle; previous result retained"
    },
    {
      "id": "idle",
      "when": true,
      "label": "Idle"
    }
  ],
  "step": [
    {
      "id": "unmount",
      "when": {
        "all": [
          {
            "eq": [
              {
                "from": "mounted"
              },
              "TRUE"
            ]
          },
          {
            "eq": [
              {
                "to": "mounted"
              },
              "FALSE"
            ]
          }
        ]
      },
      "label": "Run effect cleanup"
    },
    {
      "id": "compile",
      "when": {
        "all": [
          {
            "not": {
              "eq": [
                {
                  "from": "jobId"
                },
                {
                  "to": "jobId"
                }
              ]
            }
          },
          {
            "eq": [
              {
                "to": "status"
              },
              "\"compiling\""
            ]
          }
        ]
      },
      "label": "Start compile; replace previous job"
    },
    {
      "id": "cancel",
      "when": {
        "all": [
          {
            "not": {
              "eq": [
                {
                  "from": "jobId"
                },
                {
                  "to": "jobId"
                }
              ]
            }
          },
          {
            "eq": [
              {
                "to": "status"
              },
              "\"idle\""
            ]
          }
        ]
      },
      "label": "Cancel and clear failure"
    },
    {
      "id": "done",
      "when": {
        "all": [
          {
            "eq": [
              {
                "from": "status"
              },
              "\"compiling\""
            ]
          },
          {
            "eq": [
              {
                "to": "status"
              },
              "\"done\""
            ]
          }
        ]
      },
      "label": "Apply latest result; clear worker and timer"
    },
    {
      "id": "error",
      "when": {
        "all": [
          {
            "eq": [
              {
                "from": "status"
              },
              "\"compiling\""
            ]
          },
          {
            "eq": [
              {
                "to": "status"
              },
              "\"error\""
            ]
          }
        ]
      },
      "label": "Apply latest failure; clear worker and timer"
    },
    {
      "id": "timeout",
      "when": {
        "all": [
          {
            "eq": [
              {
                "from": "status"
              },
              "\"compiling\""
            ]
          },
          {
            "eq": [
              {
                "to": "status"
              },
              "\"timeout\""
            ]
          }
        ]
      },
      "label": "Time out latest job; clear worker and timer"
    },
    {
      "id": "stale_timeout",
      "when": {
        "not": {
          "eq": [
            {
              "from": "timeoutCount"
            },
            {
              "to": "timeoutCount"
            }
          ]
        }
      },
      "label": "Ignore replaced job's timeout"
    },
    {
      "id": "unchanged",
      "when": true,
      "label": "Wait or ignore a stale or mismatched callback"
    }
  ]
}
